'use client';
// Project A prototype uses only public state/writer exports, not package internals.
import {useEffect,useMemo,useSyncExternalStore,useId} from 'react';import {createCopyFeedback} from '@templux/web/state/copy';import {writeClipboard} from '@templux/web/elements/clipboard';import {resolveCopyMessages} from './copy-messages.mjs';
const defaults={action:'复制',pending:'正在复制',succeeded:'已复制',retry:'重试复制',empty:'暂无可复制内容。',denied:'浏览器未允许复制，请检查权限后重试。',unsupported:'此环境不支持复制，请使用安全连接和支持剪贴板的浏览器。',failed:'复制未完成，请重试。'};
export default function ProjectCopy({value,messages}:{value:string;messages:Partial<typeof defaults>}){const text=resolveCopyMessages(defaults,messages),id=useId();const store=useMemo(()=>createCopyFeedback({value,label:'Copy synthetic project reference',write:writeClipboard}),[value]),state=useSyncExternalStore(store.subscribe,store.getSnapshot,store.getSnapshot);useEffect(()=>{const end=()=>store.end();window.addEventListener('templux:session-ending',end);return()=>{window.removeEventListener('templux:session-ending',end);store.invalidate();};},[store]);if(state.ended)return null;const status=state.status,message=status==='idle'?'':text[status==='copied'?'succeeded':status];return <span data-copy-state={status}><button type="button" aria-label="Copy synthetic project reference" aria-describedby={id} disabled={status==='pending'} onClick={()=>store.copy()}>{status==='copied'?text.succeeded:status==='pending'?text.pending:['denied','unsupported','failed'].includes(status)?text.retry:text.action}</button><span id={id} role="status" aria-live="polite">{message}</span></span>;}
